-- MotorcycleSalesAPP v2 additive schema upgrade.
-- Run once in pgAdmin Query Tool against the existing MotorcycleSalesAPP database.
-- This script does not drop or truncate existing data.

ALTER TABLE "Motorcycles" ADD COLUMN IF NOT EXISTS "PurchaseCost" numeric(18,2) NOT NULL DEFAULT 0;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CustomerId" integer NULL;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "UnitCostAtSale" numeric(18,2) NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS "Customers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FullName" text NOT NULL,
  "Phone" text NULL,
  "Email" text NULL,
  "Notes" text NULL,
  "CreatedAt" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_Customers_Phone" ON "Customers" ("Phone");
CREATE INDEX IF NOT EXISTS "IX_Sales_CustomerId" ON "Sales" ("CustomerId");

CREATE TABLE IF NOT EXISTS "StockMovements" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MotorcycleId" integer NOT NULL REFERENCES "Motorcycles"("Id") ON DELETE RESTRICT,
  "MovementType" text NOT NULL,
  "Quantity" integer NOT NULL,
  "UnitCost" numeric(18,2) NOT NULL DEFAULT 0,
  "Note" text NULL,
  "SaleId" integer NULL,
  "CreatedAt" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_StockMovements_MotorcycleId_CreatedAt" ON "StockMovements" ("MotorcycleId", "CreatedAt");

CREATE TABLE IF NOT EXISTS "Expenses" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Category" text NOT NULL,
  "Description" text NOT NULL,
  "Amount" numeric(18,2) NOT NULL,
  "ExpenseDate" timestamp with time zone NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_Expenses_ExpenseDate" ON "Expenses" ("ExpenseDate");

CREATE TABLE IF NOT EXISTS "AppUsers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Username" text NOT NULL,
  "PasswordHash" text NOT NULL,
  "Role" text NOT NULL DEFAULT 'Staff',
  "IsActive" boolean NOT NULL DEFAULT true,
  "CreatedAt" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_AppUsers_Username" ON "AppUsers" ("Username");

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_Sales_Customers_CustomerId') THEN
    ALTER TABLE "Sales" ADD CONSTRAINT "FK_Sales_Customers_CustomerId"
      FOREIGN KEY ("CustomerId") REFERENCES "Customers"("Id") ON DELETE SET NULL;
  END IF;
END $$;

-- Existing sales intentionally receive UnitCostAtSale=0 because historical acquisition costs
-- are not present in the original database. Reports flag historical profit as incomplete.

-- Migrate the existing customer names into customer cards and link old sales where possible.
INSERT INTO "Customers" ("FullName", "Phone", "CreatedAt")
SELECT DISTINCT s."CustomerName", s."CustomerPhone", now()
FROM "Sales" s
WHERE NOT EXISTS (
  SELECT 1 FROM "Customers" c
  WHERE c."FullName" = s."CustomerName" AND c."Phone" IS NOT DISTINCT FROM s."CustomerPhone"
);
UPDATE "Sales" s SET "CustomerId" = c."Id"
FROM "Customers" c
WHERE s."CustomerId" IS NULL AND c."FullName" = s."CustomerName"
  AND c."Phone" IS NOT DISTINCT FROM s."CustomerPhone";

-- Record a one-time opening balance for current stock. This is the baseline from the upgrade date,
-- not a reconstruction of historical purchases/sales.
INSERT INTO "StockMovements" ("MotorcycleId", "MovementType", "Quantity", "UnitCost", "Note", "CreatedAt")
SELECT m."Id", 'OpeningBalance', m."StockQuantity", m."PurchaseCost", 'V2 geçişindeki mevcut stok bakiyesi', now()
FROM "Motorcycles" m
WHERE m."StockQuantity" > 0
  AND NOT EXISTS (SELECT 1 FROM "StockMovements" sm WHERE sm."MotorcycleId" = m."Id");
